package domain

import (
	"encoding/json"
	"fmt"
	"slices"
	"strings"
	"time"
	"unicode"
	"unicode/utf8"
)

// FactoryID is a factory's immutable metadata.id (a UUID).
type FactoryID string

// ItemID identifies a work item (a UUIDv7 generated by the store).
type ItemID string

// ItemState is where an item stands at its current station. Values match work_items.state.
type ItemState string

// Item states.
const (
	StateQueued       ItemState = "queued"
	StateReady        ItemState = "ready"
	StateInProgress   ItemState = "in_progress"
	StateWaitingHuman ItemState = "waiting_human"
	StateBlocked      ItemState = "blocked"
	StateDone         ItemState = "done"
	StateCancelled    ItemState = "cancelled"
	// StateAssembly is an item whose plan became parts (Store.Assemble): it is never claimed and
	// closes itself when its last part is done or cancelled.
	StateAssembly ItemState = "assembly"
)

// Waiting reports whether an item in this state can be pulled by the next free slot.
func (s ItemState) Waiting() bool { return s == StateQueued || s == StateReady }

// ClassOfService decides pull order: expedite items are pulled before any standard item.
type ClassOfService string

// Classes of service. Values match work_items.class_of_service.
const (
	ClassStandard ClassOfService = "standard"
	ClassExpedite ClassOfService = "expedite"
)

// Position is a station and the item's state there.
type Position struct {
	Station string
	State   ItemState
}

// Item is one unit of work flowing through a factory's line.
type Item struct {
	ID ItemID
	// OrgID is the organization the item's factory belongs to.
	OrgID     OrgID
	FactoryID FactoryID
	// Number is unique per factory and shown as <FACTORY>-<number>.
	Number   int64
	ParentID ItemID // empty when the item has no parent
	// PartKey is the part's key in its assembly's plan, empty unless the item is a part;
	// PartPaths the files the plan said it changes.
	PartKey   string
	PartPaths []string
	// Paths are the file globs the item is expected to change, nil when none are known: a part's
	// are its plan's (ADR 0012).
	Paths []string
	// BaseCommit is the default branch's head when a station with context: [inflight] last
	// finished the item, or its assembly's for a part; empty when none was recorded (ADR 0015
	// decision 5).
	BaseCommit string
	// IntegrationBranch is an assembly's integration branch, the branch its parts build on, and
	// IntegrationLandAt the station where the finished assembly lands to merge it; both empty
	// unless set, once, by ports.Store SetIntegrationBranch (flow.assemblies.integration.mode
	// branch).
	IntegrationBranch string
	IntegrationLandAt string
	// StoredBranch is the branch the store set at filing (ItemBranch), "" for an item an instance
	// from before work_items.branch filed; read it through Branch.
	StoredBranch string
	Type         string
	// Lane picks the agent at stations that route by lane. Empty until intake or an output sets it.
	Lane     string
	Title    string
	Body     string
	Station  string
	State    ItemState
	Class    ClassOfService
	Priority int
	// ReworkCount is how many times a gate or a human sent the item back upstream.
	ReworkCount int
	CostUSD     float64
	// Outputs maps a station id to the output its agent produced there.
	Outputs   map[string]json.RawMessage
	CreatedAt time.Time
	UpdatedAt time.Time
	DoneAt    time.Time // zero until the item reaches the done station
	// Source is where the item came from and Trigger the trigger that created it; "" when its
	// creator did not say.
	Source  ItemSource
	Trigger string
	// Origin is where the item came from (person, plan, trigger or follow-up), Via how a person
	// filed it ("" otherwise) and CreatedBy the filer's actor ref ("" for items filed before ADR
	// 0040). Generation counts the follow-ups it descends from; Untrusted marks work made from a
	// webhook delivery (domain.File).
	Origin     Origin
	Via        Via
	CreatedBy  string
	Generation int
	Untrusted  bool
	// StartAt is when the item may start (ADR 0040 decision 3), zero when it may start now.
	// StartedAt is when it left its line's first station, or when it was filed at a later one;
	// zero until then. Lead time counts from it.
	StartAt   time.Time
	StartedAt time.Time
	// Triage marks a factory's triage item, which collects follow-ups (ADR 0040 decision 10).
	Triage bool
}

// LeadFrom is when the item's lead time starts: StartedAt, or CreatedAt when it has not started
// (ADR 0040 decision 4).
func (it Item) LeadFrom() time.Time {
	if it.StartedAt.IsZero() {
		return it.CreatedAt
	}

	return it.StartedAt
}

// Position returns the item's station and state.
func (it Item) Position() Position { return Position{Station: it.Station, State: it.State} }

// Work is what an item asks of its agents: its title, then its body when it has one. A run's
// brief adds what the engine has for that attempt (people's notes, a rejected attempt's reason).
func (it Item) Work() string {
	if it.Body == "" {
		return it.Title
	}

	return it.Title + "\n\n" + it.Body
}

// maxSlug bounds the title part of a branch name.
const maxSlug = 40

// Branch is the git branch an item's changes live on: the one stored at filing (ItemBranch),
// so every run of the item, rework included, works on the same branch, and renaming the item or
// its factory never moves it. An item filed without one (by an instance from before
// work_items.branch) gets goal/<number>-<title slug>, what the migration backfilled.
func (it Item) Branch() string {
	if it.StoredBranch != "" {
		return it.StoredBranch
	}

	return branchName("goal/", it.Number, it.Title)
}

// ItemBranch is the branch an item filed now gets, which the store keeps:
// goal/<factory>/<number>-<title slug>, factory being the factory's name at filing, so two
// factories working in one repository never share a branch (ADR 0041 decision 6). Without a
// factory name it is goal/<number>-<title slug>.
func ItemBranch(factory string, number int64, title string) string {
	if factory == "" {
		return branchName("goal/", number, title)
	}

	return branchName("goal/"+factory+"/", number, title)
}

// BranchFactory is the factory part of a branch ItemBranch named, "" for one without (an item's
// from before ADR 0041). A part's branch names its assembly's.
func BranchFactory(branch string) string {
	rest, ok := strings.CutPrefix(branch, "goal/")
	if !ok {
		return ""
	}

	factory, _, ok := strings.Cut(rest, "/")
	if !ok {
		return ""
	}

	return factory
}

// IntegrationBranch is the git branch an assembly's parts merge into in integration mode branch:
// goal/a<root number>-<root title slug>, with the slug of Item.Branch (ADR 0033).
func IntegrationBranch(root Item) string {
	return branchName("goal/a", root.Number, root.Title)
}

// Landing reports whether it is a landing root: an assembly with an integration branch, which
// the store sets only on an assembly's root while its parts run, so the root's next claims are its
// landing at the landing station and the reworks the landing gate sends back (ADR 0033).
func (it Item) Landing() bool {
	return it.ParentID == "" && it.IntegrationBranch != ""
}

// RunBase is the branch a run of it works on, it.Branch() but for a landing root, and the base that branch is cut
// from and its pull request goes into, decided once at run start (ADR 0033). A landing root
// (Landing) works on its own integration branch, with the default branch as its base, at every
// station: its landing, and a rework of it the landing gate sent back. A part whose root
// has an integration branch builds on it, unless the part's pull request was opened against
// another base (prBase, empty while it names none), such as one opened against the default
// branch before the switch. Every other item gets an empty base: the default branch.
func RunBase(it, root Item, prBase string) (branch, base string) {
	if it.Landing() {
		return it.IntegrationBranch, ""
	}

	if it.ParentID == "" || root.IntegrationBranch == "" || (prBase != "" && prBase != root.IntegrationBranch) {
		return it.Branch(), ""
	}

	return it.Branch(), root.IntegrationBranch
}

// branchName is prefix, number and, when title has one, a dash and title's slug: lowercase
// ASCII letters and digits, each other run of characters one dash, cut near maxSlug. Migration
// 00130 computes the same in SQL for the items it backfills.
func branchName(prefix string, number int64, title string) string {
	var b strings.Builder

	dash := false

	for _, r := range strings.ToLower(title) {
		switch {
		case r < utf8.RuneSelf && (unicode.IsLetter(r) || unicode.IsDigit(r)):
			if dash && b.Len() > 0 {
				b.WriteByte('-')
			}

			dash = false

			b.WriteRune(r)
		default:
			dash = true
		}

		if b.Len() >= maxSlug {
			break
		}
	}

	slug := strings.TrimRight(b.String(), "-")
	if slug == "" {
		return fmt.Sprintf("%s%d", prefix, number)
	}

	return fmt.Sprintf("%s%d-%s", prefix, number, slug)
}

// NewItem is a filed item, as domain.File checks it, for the store to write.
type NewItem struct {
	FactoryID FactoryID
	ParentID  ItemID
	Type      string
	Lane      string
	Title     string
	Body      string
	Priority  int
	Station   string
	State     ItemState
	Class     ClassOfService
	CreatedAt time.Time
	// Source is where the item came from and Trigger the trigger that created it, for Intake; ""
	// when the creator does not say.
	Source  ItemSource
	Trigger string
	// Origin, Via, Generation and Untrusted are as on Item; the store writes OriginPerson when
	// Origin is "". CreatedBy files it: the created event's actor and the item.filed audit entry's,
	// EngineActor when zero.
	Origin     Origin
	Via        Via
	CreatedBy  Actor
	Generation int
	Untrusted  bool
	// StartAt is when the item may start, zero for now; StartedAt is CreatedAt for an item filed
	// past its line's first station, zero otherwise; After are the items it waits for, each a
	// linked edge by CreatedBy (domain.File).
	StartAt   time.Time
	StartedAt time.Time
	After     []ItemID
	// FactoryName is the factory's name at filing, which the store puts in the item's branch
	// (ItemBranch); a part's is its assembly's (BranchFactory). "" gives the branch no factory.
	FactoryName string
	// Repositories are the repositories the item starts with, in order (domain.File); the store
	// writes each with the item, joined at CreatedAt.
	Repositories []ItemRepository
}

// Assembly is an item with parts: a request split into several items (each part's ParentID is
// the assembly) that ship together.
type Assembly struct {
	ID     ItemID
	Number int64
	Title  string
	// Parts are in number order.
	Parts []Part
}

// Part is one item of an assembly, as the assembly's progress counts it.
type Part struct {
	ID      ItemID
	Number  int64
	Station string
	State   ItemState
}

// AssemblyProgress is where an assembly's parts stand: of Total, Merged are done, InProgress
// are in progress and Waiting are in any other open state (a cancelled part is in none of them).
// Stations are the distinct stations of the open parts, in part order.
type AssemblyProgress struct {
	Total, Merged, InProgress, Waiting int
	Stations                           []string
}

// Progress counts where a's parts stand.
func (a Assembly) Progress() AssemblyProgress {
	p := AssemblyProgress{Total: len(a.Parts), Stations: []string{}}

	for _, pt := range a.Parts {
		switch pt.State {
		case StateDone:
			p.Merged++
			continue
		case StateCancelled, StateAssembly: // assemblies do not nest: no part is ever an assembly
			continue
		case StateInProgress:
			p.InProgress++
		case StateQueued, StateReady, StateWaitingHuman, StateBlocked:
			p.Waiting++
		}

		if !slices.Contains(p.Stations, pt.Station) {
			p.Stations = append(p.Stations, pt.Station)
		}
	}

	return p
}

// PartNumber is item id's place among a's parts, 1-based, or 0 when it is not one of them.
func (a Assembly) PartNumber(id ItemID) int {
	for i, pt := range a.Parts {
		if pt.ID == id {
			return i + 1
		}
	}

	return 0
}
